<script setup lang="ts">
import { computed,ref } from 'vue'
import { catalogue,structureById,text,ui } from './content'
import type { EyeLocale } from './types'
const props=defineProps<{locale:EyeLocale;selected:string}>()
const emit=defineEmits<{explore:[id:string]}>()
const query=ref(''),category=ref('all'),related=ref(false),opened=ref('')
const hostname=(url:string)=>new URL(url).hostname
const results=computed(()=>catalogue.conditions.filter(c=>(category.value==='all'||c.category_ids.includes(category.value))&&(!related.value||c.anatomy_ids.includes(props.selected))&&(c.label.en+' '+c.label[props.locale]+' '+c.synonyms.join(' ')).toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
</script>
<template><section class="eye-catalogue" aria-label="Eye condition educational catalogue">
 <div class="eye-library-heading"><div><span class="eye-kicker">EYE KNOWLEDGE LIBRARY</span><h3>{{locale==='en'?'Learn the connections':locale==='ar-IQ'?'تعرف على العلاقات':'پەیوەندییەکان بناسە'}}</h3><p>{{locale==='en'?'112 starting records. Educational references, never a diagnosis inferred from your selection.':locale==='ar-IQ'?'112 سجل كبداية. مراجع تعليمية، مو تشخيص ناتج عن اختيارك.':'١١٢ تۆمار بۆ دەستپێک. سەرچاوەی فێرکاری، هەرگیز دەستنیشانکردن لەسەر بنەمای هەڵبژاردن نییە.'}}</p></div><span class="eye-count">{{results.length}} / {{catalogue.conditions.length}}</span></div>
 <div class="eye-catalogue-filters"><label>{{locale==='en'?'Search conditions':locale==='ar-IQ'?'ابحث بالحالات':'گەڕان لە نەخۆشییەکان'}}<input v-model="query" type="search"/></label><label>{{locale==='en'?'Category':locale==='ar-IQ'?'الفئة':'پۆل'}}<select v-model="category"><option value="all">{{locale==='en'?'All categories':locale==='ar-IQ'?'كل الفئات':'هەموو پۆلەکان'}}</option><option v-for="c in catalogue.categories" :key="c.id" :value="c.id">{{text(c.label,locale)}}</option></select></label><label class="eye-check"><input v-model="related" type="checkbox"/>{{locale==='en'?'Related anatomy only':locale==='ar-IQ'?'التشريح المرتبط فقط':'تەنها پێکهاتەی پەیوەندیدار'}}</label></div>
 <div class="eye-condition-grid"><article v-for="c in results" :key="c.id" class="eye-condition-card"><span class="eye-kicker">{{catalogue.categories.find(x=>x.id===c.category)?.label[locale]}} · {{c.kind}}</span><button class="eye-condition-title" :aria-expanded="opened===c.id" @click="opened=opened===c.id?'':c.id">{{c.label[locale]}}<span aria-hidden="true">{{opened===c.id?'−':'＋'}}</span></button><p>{{c.explanation[locale]}}</p><span class="eye-draft-pill">{{locale==='en'?'Draft · clinical review pending':locale==='ar-IQ'?'مسودة · بانتظار المراجعة الطبية':'ڕەشنووس · چاوەڕێی پێداچوونەوەی پزیشکی'}}</span>
 <div v-if="opened===c.id" class="eye-condition-detail"><template v-if="locale!=='en'"><p class="eye-subtle">{{text(ui.original,locale)}}</p><p lang="en" dir="ltr">{{c.explanation.en}}</p></template><dl lang="en" dir="ltr"><dt>Associated symptoms, not diagnostic</dt><dd>{{c.symptom_ids.map(id=>id.replace('symptom.','').replaceAll('-',' ')).join(', ')||'May have no reported symptoms; screening can matter.'}}</dd><dt>Risk context</dt><dd>{{c.risk_factors}}</dd><dt>Age considerations</dt><dd>{{c.age_considerations}}</dd><dt>Confirmation needs</dt><dd>{{c.confirmation}}</dd><dt>Warning signs</dt><dd>{{c.red_flags.join('; ')}}</dd><dt>Urgency</dt><dd>{{c.urgency_guidance}}</dd></dl><div class="eye-anatomy-chips"><button v-for="id in c.anatomy_ids" :key="id" @click="emit('explore',id)">{{structureById.get(id)?.label[locale]}}</button></div><a v-for="url in c.source_urls" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{hostname(url)}} · source ↗</a><p class="eye-subtle">{{c.content_version}} · Source checked {{c.source_checked_at}} · Clinical review: pending · Medical translations: pending</p></div>
 </article></div><p v-if="!results.length" class="eye-empty">{{locale==='en'?'No matching records. Try a broader search.':locale==='ar-IQ'?'ماكو نتائج. جرب بحث أوسع.':'ئەنجام نییە. گەڕانێکی فراوانتر تاقی بکەرەوە.'}}</p>
</section></template>
